// ParseTrustedCaStateServiceRpcIds converts a comma-separated string to a slice of TrustedCaStateServiceRpcId enum values
// Returns an error if any value is invalid
func ParseTrustedCaStateServiceRpcIds(s string) ([]TrustedCaStateServiceRpcId, error) {
	if s == "" {
		return nil, nil
	}
	parts := strings.Split(s, ",")
	result := make([]TrustedCaStateServiceRpcId, 0, len(parts))
	for _, part := range parts {
		trimmed := strings.TrimSpace(part)
		if trimmed == "" {
			continue
		}
		val, err := ParseTrustedCaStateServiceRpcId(trimmed)
		if err != nil {
			return nil, err
		}
		result = append(result, val)
	}
	return result, nil
}

