// ParseClusterStateServiceRpcIds converts a comma-separated string to a slice of ClusterStateServiceRpcId enum values
// Returns an error if any value is invalid
func ParseClusterStateServiceRpcIds(s string) ([]ClusterStateServiceRpcId, error) {
	if s == "" {
		return nil, nil
	}
	parts := strings.Split(s, ",")
	result := make([]ClusterStateServiceRpcId, 0, len(parts))
	for _, part := range parts {
		trimmed := strings.TrimSpace(part)
		if trimmed == "" {
			continue
		}
		val, err := ParseClusterStateServiceRpcId(trimmed)
		if err != nil {
			return nil, err
		}
		result = append(result, val)
	}
	return result, nil
}

