// ParseServiceHealthStateServiceRpcIds converts a comma-separated string to a slice of ServiceHealthStateServiceRpcId enum values
// Returns an error if any value is invalid
func ParseServiceHealthStateServiceRpcIds(s string) ([]ServiceHealthStateServiceRpcId, error) {
	if s == "" {
		return nil, nil
	}
	parts := strings.Split(s, ",")
	result := make([]ServiceHealthStateServiceRpcId, 0, len(parts))
	for _, part := range parts {
		trimmed := strings.TrimSpace(part)
		if trimmed == "" {
			continue
		}
		val, err := ParseServiceHealthStateServiceRpcId(trimmed)
		if err != nil {
			return nil, err
		}
		result = append(result, val)
	}
	return result, nil
}

