// ParseCaStateServiceRpcIds converts a comma-separated string to a slice of CaStateServiceRpcId enum values
// Returns an error if any value is invalid
func ParseCaStateServiceRpcIds(s string) ([]CaStateServiceRpcId, error) {
	if s == "" {
		return nil, nil
	}
	parts := strings.Split(s, ",")
	result := make([]CaStateServiceRpcId, 0, len(parts))
	for _, part := range parts {
		trimmed := strings.TrimSpace(part)
		if trimmed == "" {
			continue
		}
		val, err := ParseCaStateServiceRpcId(trimmed)
		if err != nil {
			return nil, err
		}
		result = append(result, val)
	}
	return result, nil
}

