// ParseConfigStateServiceRpcIds converts a comma-separated string to a slice of ConfigStateServiceRpcId enum values
// Returns an error if any value is invalid
func ParseConfigStateServiceRpcIds(s string) ([]ConfigStateServiceRpcId, error) {
	if s == "" {
		return nil, nil
	}
	parts := strings.Split(s, ",")
	result := make([]ConfigStateServiceRpcId, 0, len(parts))
	for _, part := range parts {
		trimmed := strings.TrimSpace(part)
		if trimmed == "" {
			continue
		}
		val, err := ParseConfigStateServiceRpcId(trimmed)
		if err != nil {
			return nil, err
		}
		result = append(result, val)
	}
	return result, nil
}

