// ============================================================
// TypeDefaults: Config
// ============================================================
// ConfigDefaults applies field-level default values to zero-valued fields.
func ConfigDefaults(v *Config) {
	if v == nil {
		return
	}
	if v.PartitionCount == 0 {
		v.PartitionCount = int32(DefaultPartitionCount)
	}
	if v.DiskDir == "" {
		v.DiskDir = DefaultDiskDir
	}
	if v.KeyRotationIntervalSeconds == 0 {
		v.KeyRotationIntervalSeconds = DefaultKeyRotationIntervalSeconds
	}
	if v.DefaultTokenExpirySeconds == 0 {
		v.DefaultTokenExpirySeconds = DefaultDefaultTokenExpirySeconds
	}
	if v.CaCertLifetimeSeconds == 0 {
		v.CaCertLifetimeSeconds = DefaultCaCertLifetimeSeconds
	}
	if v.AccessTokenLifetimeSeconds == 0 {
		v.AccessTokenLifetimeSeconds = DefaultAccessTokenLifetimeSeconds
	}
	if v.RefreshTokenLifetimeSeconds == 0 {
		v.RefreshTokenLifetimeSeconds = DefaultRefreshTokenLifetimeSeconds
	}
	if v.TlsCertLifetimeSeconds == 0 {
		v.TlsCertLifetimeSeconds = DefaultTlsCertLifetimeSeconds
	}
	if v.MaxTokenLifetimeSeconds == 0 {
		v.MaxTokenLifetimeSeconds = DefaultMaxTokenLifetimeSeconds
	}
	if v.OfflineTokenLifetimeSeconds == 0 {
		v.OfflineTokenLifetimeSeconds = DefaultOfflineTokenLifetimeSeconds
	}
	if v.SpiffeTrustDomain == "" {
		v.SpiffeTrustDomain = DefaultSpiffeTrustDomain
	}
	if v.HealthProbePort == 0 {
		v.HealthProbePort = int32(DefaultHealthProbePort)
	}
	if v.Listener == nil {
		v.Listener = &host.Host{Host: "0.0.0.0", Port: 5000}
	}
	if v.HazelcastListener == nil {
		v.HazelcastListener = &host.Host{Host: "0.0.0.0", Port: 5001}
	}
	if v.RatisListener == nil {
		v.RatisListener = &host.Host{Host: "0.0.0.0", Port: 5002}
	}
}

